    private void makeUnlessTaken(String sheetId, String user, List<Period> existing, List<Period> made,
            String name, LocalDate first, LocalDate last) {
        if (existing.stream().anyMatch(p -> p.getNameKey().equals(Period.keyOf(name)) || p.overlaps(first, last))) {
            return;
        }
        Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
        existing.add(saved);
        made.add(saved);
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " from=" + saved.getFrom() + " to=" + saved.getTo());
    }

    /** Close a period, fixing at this moment its due-total and each person's due-total for it: the figures as shown now of the claims
     *  due by a date in it that were open or settled at the end of its last day (by their status logs), skipping those that are n/a and the unbound open claims of a person whose retirement date is reached, and the claims deferred on the sheet's today; and each person's carried figure for it: the figures as shown now of their claims counted so that belong to a period ending before it starts and were still open (PENDING included) at its end, with their opening balance for it. A soft-closed period is closed with its figures fixed afresh. Refused when the period is already closed, or the sheet's permission matrix does not allow the user's role to close. */
    @Transactional
    public Period close(String sheetId, String user, long id) {
        // Locked as claim changes lock it, so no claim in the period changes while it is closed.
        sheetRows.findForUpdate(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessPermitted(sheetId, user, "close", "Your role may not close a period on this sheet.");
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
        }
        return closeNow(sheetId, user, period, false, false);
    }

    /** Soft-close a period: its due-total and each person's due-total for it are fixed at this moment as
     *  a close fixes them, while claims dated in it can still be added and changed. Refused when the
     *  period is closed or soft-closed already, or the sheet's permission matrix does not allow the
     *  user's role to close. */
    @Transactional
    public Period softClose(String sheetId, String user, long id) {
        sheetRows.findForUpdate(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessPermitted(sheetId, user, "close", "Your role may not close a period on this sheet.");
        if (period.isClosed() || period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
        }
        return closeNow(sheetId, user, period, false, true);
    }

    /** Once the sheet's today is changed, close each open period whose to-date plus the sheet's grace days
     *  is before the new today (a soft-closed period keeps the figures fixed when it was soft-closed), in order of their to-dates, as a close by hand would; none when the grace
     *  days are blank. Each is audited as closed automatically. */
    @EventListener
    @Transactional
    public void closeOverdue(TodayChanged change) {
        Integer grace = settings.graceDays(change.sheetId());
        if (grace == null) return;
        sheetRows.findForUpdate(change.sheetId());
        List<Period> due = periods.findBySheetIdOrderByFromAsc(change.sheetId()).stream()
                .filter((p) -> !p.isClosed() && !p.isSoftClosed() && p.getTo().plusDays(grace).isBefore(change.today()))
                .sorted(Comparator.comparing(Period::getTo)).toList();
        for (Period period : due) closeNow(change.sheetId(), change.user(), period, true, false);
    }

    /** Close (or soft-close) a period now, fixing its figures; the audit line marks a close the today change made. */
    private Period closeNow(String sheetId, String user, Period period, boolean auto, boolean soft) {
        Map<Long, Person> peopleById = people.findInListOrder(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        LocalDate today = sheets.today(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new HashMap<>();
        Map<Long, BigDecimal> personCarried = new HashMap<>();
        for (Long personId : peopleById.keySet()) {
            personTotals.put(personId, BigDecimal.ZERO.setScale(2));
            personCarried.put(personId, period.openingOf(personId));
        }
        List<Period> all = periods.findBySheetIdOrderByFromAsc(sheetId);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = peopleById.get(claim.getPersonId());
            if (person == null) continue;
            // Counted by the status the claim had at the end of the period's last day; a reached retirement
            // only leaves out a claim still open now, as it touches only live claims. A hold leaves none out.
            ClaimStatus then = claim.statusAsOf(period.getTo());
            if (!counts(claim, person, then, today)) continue;
            // Carried: still open at the end of this period, belonging to a period ending before it starts.
            boolean carried = then.isOpen() && all.stream()
                    .anyMatch((p) -> p.contains(claim.getDueBy()) && p.getTo().isBefore(period.getFrom()));
            if (!carried && !period.contains(claim.getDueBy())) continue;
            BigDecimal due = claimService.due(sheetId, person, claim);
            if (due == null) continue;
            if (carried) {
                personCarried.merge(person.getId(), due, BigDecimal::add);
            } else {
                total = total.add(due);
                personTotals.merge(person.getId(), due, BigDecimal::add);
            }
        }
        if (soft) period.softClose(total, personTotals, personCarried);
        else period.close(total, personTotals, personCarried);
        // Every pool member's cut for the period is fixed as it stands now, the sheet's today as it is.
        period.fixPoolCuts(PoolCuts.of(pools.findBySheetIdOrderByIdAsc(sheetId),
                crews.findBySheetIdOrderByIdAsc(sheetId), people.findInListOrder(sheetId), settings.pot(sheetId), today));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + total.toPlainString() + (auto ? " auto=yes" : ""));
        return saved;
    }

    /** Whether a claim counts toward a period's figures, by the status it had at the end of the period's
     *  last day: open or settled then, not deferred on the sheet's today, and, when unbound and open still,
     *  its person's retirement date not reached. */
    private static boolean counts(Claim claim, Person person, ClaimStatus then, LocalDate today) {
        return then != null && !claim.isDeferredOn(today) && (then == ClaimStatus.SETTLED
                || (then.isOpen() && (claim.isStated() || !claim.getStatus().isOpen() || !person.isRetiredBy(today))));
    }

    /** Roll a fiscal year over: generate the next fiscal year's twelve monthly periods as
     *  {@link #generateFiscalYear} does, then add to each person's opening balance for the new year's first
     *  period their open figure at the end of the old year's last period: the due of their claims that
     *  count, belonging to a period of the old year, and OPEN or PENDING at that period's end; none when the
     *  year has been rolled over already and that rollover is not undone. Refused unless
     *  the user acts as a steward, and when the old year has no periods. The periods made, in date order. */
    @Transactional
    public List<Period> rollover(String sheetId, String user, int year) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may roll the year over.");
        }
        YearMonth first = YearMonth.of(year, settings.fiscalStartMonth(sheetId));
        LocalDate oldFrom = first.atDay(1);
        LocalDate oldTo = first.plusMonths(11).atEndOfMonth();
        List<Period> oldYear = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter((p) -> !p.getFrom().isBefore(oldFrom) && !p.getTo().isAfter(oldTo)).toList();
        if (oldYear.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The fiscal year FY" + year + " has no periods.");
        }
        Period last = oldYear.stream().max(Comparator.comparing(Period::getTo)).orElseThrow();
        LocalDate today = sheets.today(sheetId);
        List<Person> listed = people.findInListOrder(sheetId);
        Map<Long, Person> peopleById = listed.stream().collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, BigDecimal> open = new HashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = peopleById.get(claim.getPersonId());
            if (person == null) continue;
            ClaimStatus then = claim.statusAsOf(last.getTo());
            if (!counts(claim, person, then, today) || !then.isOpen()) continue;
            if (oldYear.stream().noneMatch((p) -> p.contains(claim.getDueBy()))) continue;
            BigDecimal due = claimService.due(sheetId, person, claim);
            if (due != null) open.merge(person.getId(), due, BigDecimal::add);
        }

        List<Period> made = generateMonths(sheetId, user, first.plusMonths(12), first.plusMonths(23));
        Rollover rollover = new Rollover(sheetId, year, user, today);
        made.forEach((p) -> rollover.getPeriodIds().add(p.getId()));
        LocalDate newFrom = first.plusMonths(12).atDay(1);
        LocalDate newTo = first.plusMonths(23).atEndOfMonth();
        Period opening = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter((p) -> !p.getFrom().isBefore(newFrom) && !p.getTo().isAfter(newTo)).findFirst().orElse(null);
        // A year rolled over already, and not undone, has carried its open figures; they are not carried twice.
        boolean carried = rollovers.existsBySheetIdAndYearAndUndoneFalse(sheetId, year);
        if (opening != null && !carried) {
            for (Person person : listed) {
                BigDecimal amount = open.get(person.getId());
                if (amount == null || amount.signum() == 0) continue;
                opening.addOpening(person.getId(), amount);
                rollover.getOpenings().merge(person.getId(), amount.setScale(2), BigDecimal::add);
                audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                        + " period=" + opening.getName() + " amount=" + amount.setScale(2).toPlainString());
            }
            periods.saveAndFlush(opening);
            rollover.setOpeningPeriodId(opening.getId());
        }
        rollovers.saveAndFlush(rollover);
        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + user + " fy=FY" + year + " periods=" + made.size());
        return made;
    }

    /** Undo the sheet's last rollover: remove the periods it generated and take back the opening balances it
     *  added. Refused unless the user made it, and on the sheet's today it was made on; when it is undone
     *  already, there is none, or a claim belongs to (is due by a date in) a period it generated. */
    @Transactional
    public void undoRollover(String sheetId, String user) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        Rollover rollover = rollovers.findFirstBySheetIdOrderByIdDesc(sheetId).filter((r) -> !r.isUndone())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "There is no rollover to undo."));
        if (!rollover.getMadeBy().equals(user) || settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only the steward who rolled the year over may undo it.");
        }
        if (!rollover.getMadeOn().equals(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A rollover can be undone only on the day it was made.");
        }
        List<Period> generated = periods.findAllById(rollover.getPeriodIds());
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        if (all.stream().anyMatch((c) -> generated.stream().anyMatch((p) -> p.contains(c.getDueBy())))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A claim belongs to a period the rollover generated.");
        }
        if (rollover.getOpeningPeriodId() != null && !rollover.getPeriodIds().contains(rollover.getOpeningPeriodId())) {
            periods.findByIdAndSheetId(rollover.getOpeningPeriodId(), sheetId).ifPresent((opening) -> {
                rollover.getOpenings().forEach(opening::takeBackOpening);
                periods.saveAndFlush(opening);
            });
        }
        periods.deleteAll(generated);
        rollover.undo();
        rollovers.saveAndFlush(rollover);
        audit.recordOnCommit("ROLLOVER_UNDONE sheet=" + sheetId + " by=" + user + " fy=FY" + rollover.getYear());
    }

    /** Reopen a closed or soft-closed period, making its due-total and its pool members' cuts live again. Refused when the sheet's permission
     *  matrix does not allow the user's role to reopen (by default, only a steward), or the period is not closed. */
    @Transactional
    public Period reopen(String sheetId, String user, long id) {
        // Locked as closing locks it, so a reopen and a close of the period do not cross.
        sheetRows.findForUpdate(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
        settings.refuseUnlessPermitted(sheetId, user, "reopen", "Your role may not reopen a period on this sheet.");
        if (period.isLocked()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is locked.");
        }
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is not closed.");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
